// The generated WASM bindings, used in browsers and Node.js.
//
// On React Native (iOS/Android), Metro instead resolves `./bindings` to
// `bindings.native.ts`, which uses the JSI bindings. Both are generated by
// uniffi-bindgen-react-native from the same Rust crate, so they expose the
// same API, and the wrappers in this directory can use either.
//
// We use platform extensions instead of conditional package.json `imports`,
// since `@react-native/typescript-config` disables `resolvePackageJsonImports`,
// which would break type-checking React Native apps that use this package.
export * from "./wasm/nobodywho";
export { default } from "./wasm/nobodywho";
